CREATE TABLE "schema_version" ("version" integer not null);
CREATE TABLE "users" ("id" text primary key, "handle" text not null unique, "name" text not null, "email" text unique, "inactive" integer default 0 not null, "created_at" bigint not null);
CREATE TABLE "teams" ("id" text primary key, "handle" text not null unique, "name" text not null, "description" text not null, "created_by" text not null, "created_at" bigint not null, "archived" integer default 0 not null, "create_policy" text not null, "defaults" text not null, "requirements" text not null);
CREATE TABLE "groups" ("id" text primary key, "handle" text not null unique, "name" text not null, "description" text not null, "created_by" text not null, "created_at" bigint not null, "deleted_at" bigint);
CREATE TABLE "memberships" ("kind" text not null, "container" text not null, "user" text not null, "role" text not null, "created_at" bigint not null, constraint "memberships_pk" primary key ("kind", "container", "user"));
CREATE INDEX "memberships_user" on "memberships" ("user", "kind", "container");
CREATE TABLE "team_groups" ("team" text not null, "group" text not null, "role" text not null, "added_by" text not null, "created_at" bigint not null, constraint "team_groups_pk" primary key ("team", "group"));
CREATE INDEX "team_groups_group" on "team_groups" ("group", "team");
CREATE TABLE "join_requests" ("kind" text not null, "container" text not null, "user" text not null, "created_at" bigint not null, constraint "join_requests_pk" primary key ("kind", "container", "user"));
CREATE TABLE "ideas" ("id" text primary key, "title" text not null, "team" text, "owner" text not null, "status" text not null, "latest" integer not null, "created_at" bigint not null, "updated_at" bigint not null, "place" text not null, "number" integer not null, "description" text default '' not null, "open_comments" integer default 0 not null, "approvers" text default '[]' not null);
CREATE UNIQUE INDEX "ideas_place" on "ideas" ("place", "number");
CREATE TABLE "numbering" ("place" text primary key, "next" integer not null);
CREATE TABLE "idea_aliases" ("place" text not null, "number" integer not null, "idea" text not null, constraint "idea_aliases_pk" primary key ("place", "number"));
CREATE TABLE "handle_aliases" ("kind" text not null, "handle" text not null, "owner" text not null, "created_at" bigint not null, constraint "handle_aliases_pk" primary key ("kind", "handle"));
CREATE INDEX "ideas_updated" on "ideas" ("updated_at", "id");
CREATE INDEX "ideas_team" on "ideas" ("team", "updated_at", "id");
CREATE INDEX "ideas_owner" on "ideas" ("owner", "updated_at", "id");
CREATE TABLE "grants" ("idea" text not null, "kind" text not null, "subject" text not null, "can_edit" integer not null, "can_share" integer not null, "reviewer" integer default 0 not null, "created_at" bigint not null, "asked_at" bigint, "asked_by" text, constraint "grants_pk" primary key ("idea", "kind", "subject"));
CREATE INDEX "grants_subject" on "grants" ("kind", "subject", "idea");
CREATE TABLE "token_grants" ("id" text primary key, "user" text not null, "purpose" text not null, "bot" text, "read_only" integer not null, "limited" integer not null, "created_at" bigint not null, "revoked_at" bigint);
CREATE INDEX "token_grants_user" on "token_grants" ("user", "created_at");
CREATE TABLE "token_grant_targets" ("token_grant" text not null, "kind" text not null, "target" text not null, constraint "token_grant_targets_pk" primary key ("token_grant", "kind", "target"));
CREATE TABLE "inbox_events" ("id" text primary key, "idea" text not null, "kind" text not null, "actor" text not null, "by_user" text, "at" bigint not null, "detail" text not null);
CREATE INDEX "inbox_events_idea" on "inbox_events" ("idea", "at");
CREATE TABLE "inbox" ("user" text not null, "idea" text not null, "reason" text not null, "event" text not null, "new_count" integer not null, "done" integer not null, "updated_at" bigint not null, constraint "inbox_pk" primary key ("user", "idea"));
CREATE INDEX "inbox_user" on "inbox" ("user", "done", "updated_at", "idea");
CREATE TABLE "notices" ("id" text primary key, "user" text not null, "kind" text not null, "team" text, "group" text, "actor" text not null, "at" bigint not null, "detail" text not null, "read" integer not null, "done" integer not null, "email" integer not null);
CREATE INDEX "notices_user" on "notices" ("user", "done", "at", "id");
CREATE INDEX "notices_email" on "notices" ("email", "at");
CREATE TABLE "subscriptions" ("user" text not null, "idea" text not null, "state" text not null, "at" bigint not null, constraint "subscriptions_pk" primary key ("user", "idea"));
CREATE INDEX "subscriptions_idea" on "subscriptions" ("idea", "state");
CREATE TABLE "watches" ("user" text not null, "team" text not null, "level" text not null, "at" bigint not null, constraint "watches_pk" primary key ("user", "team"));
CREATE TABLE "watch_marks" ("user" text not null, "idea" text not null, "read_at" bigint not null, "done_at" bigint, constraint "watch_marks_pk" primary key ("user", "idea"));
CREATE TABLE "notification_settings" ("user" text primary key, "own_bots" integer not null, "email" text not null, "email_watching" integer not null, "cadence" text not null, "digest_at" bigint);
CREATE TABLE "email_pending" ("user" text not null, "idea" text not null, "event" text not null, "reason" text not null, "queued_at" bigint not null, constraint "email_pending_pk" primary key ("user", "event"));
CREATE INDEX "email_pending_user" on "email_pending" ("user", "idea");
CREATE TABLE "email_queue" ("user" text not null, "idea" text not null, "first" bigint not null, "last" bigint not null, "daily" integer not null, constraint "email_queue_pk" primary key ("user", "idea"));
CREATE INDEX "email_queue_last" on "email_queue" ("daily", "last");
CREATE INDEX "email_queue_first" on "email_queue" ("daily", "first");
INSERT INTO schema_version (version) VALUES (1);
